def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    marker = next((v for v in colors if v not in (0, 9)), None)
    if marker is None:
        return [row[:] for row in grid]

    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == marker]
    minr = min(r for r, c in pts)
    maxr = max(r for r, c in pts)
    minc = min(c for r, c in pts)
    maxc = max(c for r, c in pts)
    shape = [(r - minr, c - minc) for r, c in pts]
    out = [row[:] for row in grid]

    for r0 in range(h - (maxr - minr + 1) + 1):
        for c0 in range(w - (maxc - minc + 1) + 1):
            cells = [(r0 + dr, c0 + dc) for dr, dc in shape]
            if all(grid[r][c] == 0 for r, c in cells):
                for r, c in cells:
                    out[r][c] = marker
    return out
